  `menu_item_code` varchar(100) NOT NULL,
  `order_id` varchar(50) NOT NULL,
  `user_email` varchar(150) NOT NULL,
  `user_name` varchar(150) DEFAULT NULL,
  `rating` tinyint NOT NULL,
  `comment` text,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_review_order_user_item` (`order_id`,`user_email`,`menu_item_code`),
  KEY `fk_food_review_menu_item` (`menu_item_id`),
  CONSTRAINT `fk_food_review_menu_item` FOREIGN KEY (`menu_item_id`) REFERENCES `menu_items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
