DROP TABLE IF EXISTS `menu_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `menu_items` (
  `id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(100) NOT NULL,
  `category_id` int DEFAULT NULL,
  `name` varchar(150) NOT NULL,
  `description` text,
  `price` decimal(12,2) NOT NULL,
  `type` varchar(50) DEFAULT 'Món chính',
  `image` varchar(255) DEFAULT NULL,
  `images` json DEFAULT NULL,
  `status` enum('available','unavailable','deleted','selling','paused','stopped') DEFAULT 'selling',
  `badge` varchar(100) DEFAULT '',
  `sold` int DEFAULT '0',
  `rating` decimal(2,1) DEFAULT '0.0',
  `reviews` int DEFAULT '0',
  `short_description` text,
  `ingredients` text,
  `flavor` text,
  `highlights` text,
  `portion` varchar(100) DEFAULT '',
  `cooking` varchar(100) DEFAULT '',
  `time` varchar(100) DEFAULT '',
  `parent_category` varchar(100) DEFAULT '',
  `sub_category` varchar(100) DEFAULT '',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `cost_price` decimal(15,2) DEFAULT '0.00',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_menu_code` (`code`),
  KEY `fk_menu_category` (`category_id`),
  CONSTRAINT `fk_menu_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=349 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
