INSERT INTO `menu_items` VALUES (1,'DE001',1,'Dê test','Món test',100000.00,'Món chính','http://localhost:5001/uploads/menu/menu-1782409105505-381885001.jpg','[\"http://localhost:5001/uploads/menu/menu-1782409105505-381885001.jpg\"]','deleted','',0,0.0,0,'','','Hương vị xém than thơm lừng, thịt đậm đà thấm vị ướp, béo ngậy vừa vặn.','Thịt dê ướp sốt đậm đà, dậy mùi thơm lừng\nNướng than hoa chín tới, ngoài xém trong mọng nước\nĂn kèm rau rừng, đồ chua và chao chấm đặc chế\nMón nhậu lai rai khoái khẩu chuẩn vị','Đĩa 2 - 3 người','Nướng than hoa vàng xém','15 - 20 phút','Dê nướng','','2026-06-25 17:08:15','2026-09-09 18:57:51',0.00),(2,'DE002',2,'Dê Tùng Xẻo','Nguyễn Đình Phú',529000.00,'Món chính','http://localhost:5001/uploads/menu/menu-1782409105505-381885001.jpg','[\"http://localhost:5001/uploads/menu/menu-1782409105505-381885001.jpg\", \"http://localhost:5001/uploads/menu/menu-1782409077190-252443977.jpg\", \"http://localhost:5001/uploads/menu/menu-1782409077194-490523196.jpg\", \"http://localhost:5001/uploads/menu/menu-1782409077206-206424718.jpg\", \"http://localhost:5001/uploads/menu/menu-1782409077209-269817683.png\"]','selling','Đặc sản',0,5.0,2,'Món ăn đặc sản HS','Ba chỉ, \nSườn dê\nDê thui','Đậm đà\nThanh ngọt','Thịt dê tươi hấp chín tới, giữ trọn vị ngọt nguyên bản\nThơm lừng hương lá tía tô và gừng sả\nThịt mềm ngọt, không ngấy, tốt cho sức khỏe\nChấm kèm tương gừng gia truyền đậm vị','Đĩa 2 - 3 người','Hấp tía tô nóng hổi','10 - 15 phút','Dê hấp','','2026-06-25 17:11:27','2026-09-09 18:57:51',0.00),(17,'de-nhung-dam',6,'Dê nhúng dấm','Thịt dê thái mỏng nhúng nước dấm chua dịu, ăn kèm rau sống, bún và nước chấm.',400000.00,'food','http://localhost:5001/uploads/menu/menu-1784042366040-913928498.jpg','[\"http://localhost:5001/uploads/menu/menu-1784042366040-913928498.jpg\"]','selling','',0,5.0,0,'Thịt dê thái mỏng nhúng nước dấm chua dịu, ăn kèm rau sống, bún và nước chấm.','Thịt dê, dấm, sả, hành, rau sống, bún, nước chấm','Đậm đà chuẩn vị, giữ trọn độ n