DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_code` varchar(50) NOT NULL,
  `customer_name` varchar(150) DEFAULT NULL,
  `phone` varchar(30) DEFAULT NULL,
  `email` varchar(150) DEFAULT NULL,
  `service_type` varchar(50) DEFAULT NULL,
  `table_code` varchar(50) DEFAULT NULL,
  `guests` int DEFAULT '0',
  `address` text,
  `receiver` varchar(150) DEFAULT NULL,
  `payment_method` varchar(50) DEFAULT NULL,
  `payment_status` varchar(50) DEFAULT NULL,
  `status` varchar(100) DEFAULT NULL,
  `subtotal` decimal(12,2) DEFAULT '0.00',
  `shipping_fee` decimal(12,2) DEFAULT '0.00',
  `discount_total` decimal(12,2) DEFAULT '0.00',
  `coupon_discount_total` decimal(12,2) DEFAULT '0.00',
  `total` decimal(12,2) DEFAULT '0.00',
  `applied_coupon` json DEFAULT NULL,
  `payment_content` varchar(255) DEFAULT NULL,
  `sepay_transaction` json DEFAULT NULL,
  `sepay_amount` decimal(12,2) DEFAULT '0.00',
  `paid_at` datetime DEFAULT NULL,
  `raw_data` json DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_code` (`order_code`)
) ENGINE=InnoDB AUTO_INCREMENT=94 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
